START TRANSACTION;
SET FOREIGN_KEY_CHECKS=0;
TRUNCATE attendance_logs;
TRUNCATE attendance_daily_summary;
TRUNCATE attendance_employee_shift;
TRUNCATE attendance_corrections;
TRUNCATE attendance_monthly_approval;
TRUNCATE leave_requests;
TRUNCATE don_nghi_phep;
TRUNCATE ot_requests;
TRUNCATE shift_change_requests;
TRUNCATE employee_timesheet_approval;
DELETE FROM nguoidung WHERE chucVu = 'Nhân viên';
DELETE t FROM taikhoan t LEFT JOIN nguoidung n ON n.maTK = t.maTK WHERE n.maTK IS NULL;
SET FOREIGN_KEY_CHECKS=1;
COMMIT;
START TRANSACTION;
SET FOREIGN_KEY_CHECKS=0;
SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
SET @base_id := (SELECT GREATEST((SELECT IFNULL(MAX(maTK), 0) FROM taikhoan), (SELECT IFNULL(MAX(maND), 0) FROM nguoidung)));
SET FOREIGN_KEY_CHECKS=1;
COMMIT;

